select.where:
m.is_active = 1

    AND (
        m.product_name like concat('%', #{keyword}, '%')
        OR m.product_alias like concat('%', #{keyword}, '%')
        OR m.product_english_name like concat('%', #{keyword}, '%')
        OR m.cas_number like concat('%', #{keyword}, '%')
        OR m.company_name like concat('%', #{keyword}, '%')
    )



        AND m.status = #{filters.documentType}


        AND m.category_id = #{filters.categoryId}


        AND m.company_name like concat('%', #{filters.supplier}, '%')


        AND m.update_time >= #{filters.updateTimeFrom}


        AND m.update_time <= #{filters.updateTimeTo}
